import { Boom } from '@hapi/boom'
import { proto } from '../../WAProto/index.js'
import { DEFAULT_CACHE_TTLS, WA_DEFAULT_EPHEMERAL } from '../Defaults/index.js'
import type {
  AnyMessageContent,
  MediaConnInfo,
  MessageReceiptType,
  MessageRelayOptions,
  MiscMessageGenerationOptions,
  SocketConfig,
  WAMessage,
  WAMessageKey
} from '../Types/index.js'
import {
  aggregateMessageKeysNotFromMe,
  assertMediaContent,
  bindWaitForEvent,
  decryptMediaRetryData,
  delay,
  encodeNewsletterMessage,
  encodeSignedDeviceIdentity,
  encodeWAMessage,
  encryptMediaRetryRequest,
  extractDeviceJids,
  generateMessageIDV2,
  generateParticipantHashV2,
  generateWAMessage,
  getStatusCodeForMediaRetry,
  getUrlFromDirectPath,
  getWAUploadToServer,
  MessageRetryManager,
  normalizeMessageContent,
  parseAndInjectE2ESessions,
  unixTimestampSeconds
} from '../Utils/index.js'
import { getUrlInfo } from '../Utils/link-preview.js'
import { makeKeyedMutex } from '../Utils/make-mutex.js'
import {
  getKeysLimit,
  markKeySentToParticipant,
  PRIORITY_PARTICIPANTS_CACHE,
  shouldSendKeyToParticipant
} from '../Utils/priority-participants.js'
import {
  areJidsSameUser,
  type BinaryNode,
  type BinaryNodeAttributes,
  type FullJid,
  getBinaryNodeChild,
  getBinaryNodeChildren,
  isHostedLidUser,
  isHostedPnUser,
  isJidGroup,
  isLidUser,
  isPnUser,
  jidDecode,
  jidEncode,
  jidNormalizedUser,
  type JidWithDevice,
  S_WHATSAPP_NET
} from '../WABinary/index.js'
import { USyncQuery, USyncUser } from '../WAUSync/index.js'
import { makeNewsletterSocket } from './newsletter.js'

export const makeMessagesSocket = (config: SocketConfig) => {
	const {
		logger,
		linkPreviewImageThumbnailWidth,
		generateHighQualityLinkPreview,
		options: httpRequestOptions,
		patchMessageBeforeSending,
		cachedGroupMetadata,
		enableRecentMessageCache,
		maxMsgRetryCount
	} = config
	const sock = makeNewsletterSocket(config)
	const {
		ev,
		authState,
		processingMutex,
		signalRepository,
		upsertMessage,
		query,
		fetchPrivacySettings,
		sendNode,
		groupMetadata,
		groupToggleEphemeral
	} = sock

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Sistema de verificação para grupos fechados
	 * 
	 * PROBLEMA: Quando o bot recebe admin em grupo fechado, o cache local pode
	 * não estar atualizado. Se o bot enviar mensagem antes do cache atualizar,
	 * o WhatsApp pode detectar inconsistência e banir o número.
	 * 
	 * SOLUÇÃO: Verificar se o grupo é fechado e se o bot é admin antes de enviar.
	 * Se houver inconsistência, aguardar ou buscar metadados frescos.
	 */
	const ANNOUNCE_GROUP_PROTECTION = {
		// Cache de quando o bot foi promovido a admin (groupJid -> timestamp)
		recentPromotions: new Map<string, number>(),
		// Tempo mínimo para aguardar após promoção antes de enviar (5 segundos)
		PROMOTION_COOLDOWN_MS: 5000,
		// Cache de verificação de admin (groupJid -> { isAdmin, lastCheck })
		adminStatusCache: new Map<string, { isAdmin: boolean; lastCheck: number }>(),
		// TTL do cache de status de admin (30 segundos)
		ADMIN_CACHE_TTL_MS: 30000,
		// Grupos onde já verificamos que não somos admin (evita loops)
		notAdminGroups: new Set<string>()
	}

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Sistema de cooldown quando bot é adicionado a grupos
	 * 
	 * PROBLEMA: Quando o bot é adicionado a QUALQUER grupo enquanto está online,
	 * operações automáticas do Baileys podem gerar flood de requisições,
	 * causando banimento por comportamento suspeito.
	 * 
	 * SOLUÇÃO: Detectar quando o bot é adicionado e aplicar cooldown SEMPRE
	 * antes de permitir qualquer operação de envio nesse grupo.
	 * 
	 * NOTA: O cooldown é aplicado para TODOS os grupos, não apenas grandes,
	 * pois o problema pode ocorrer em qualquer tamanho de grupo.
	 */
	const BOT_ENTRY_PROTECTION = {
		// Cache de quando o bot foi adicionado a grupos (groupJid -> timestamp)
		recentEntries: new Map<string, number>(),
		// Cooldown MÍNIMO para qualquer grupo (segurança base): 8 segundos
		MIN_COOLDOWN_MS: 8000,
		// Cooldown após ser adicionado a grupo pequeno (< 100 membros): 8 segundos
		SMALL_GROUP_COOLDOWN_MS: 8000,
		// Cooldown após ser adicionado a grupo médio (100-300 membros): 12 segundos
		MEDIUM_GROUP_COOLDOWN_MS: 12000,
		// Cooldown após ser adicionado a grupo grande (300-600 membros): 18 segundos
		LARGE_GROUP_COOLDOWN_MS: 18000,
		// Cooldown após ser adicionado a grupo muito grande (> 600 membros): 25 segundos
		VERY_LARGE_GROUP_COOLDOWN_MS: 25000,
		// Cache de tamanho de grupos (groupJid -> memberCount)
		groupSizeCache: new Map<string, number>()
	}

	/**
	 * Verifica se o bot é admin no grupo
	 */
	const isBotAdminInGroup = (groupData: any, meId: string, meLid?: string): boolean => {
		if (!groupData?.participants) return false
		
		const meUser = jidDecode(meId)?.user
		const meLidUser = meLid ? jidDecode(meLid)?.user : null
		
		for (const p of groupData.participants) {
			const participantUser = jidDecode(p.id)?.user
			const isMe = participantUser === meUser || (meLidUser && participantUser === meLidUser)
			
			if (isMe && (p.admin === 'admin' || p.admin === 'superadmin')) {
				return true
			}
		}
		
		return false
	}

	/**
	 * Verifica segurança antes de enviar em grupo fechado
	 * Retorna true se é seguro enviar, false se deve aguardar/bloquear
	 */
	const checkAnnounceGroupSafety = async (
		jid: string, 
		groupData: any
	): Promise<{ safe: boolean; reason?: string; shouldRefresh?: boolean }> => {
		const meId = authState.creds.me!.id
		const meLid = authState.creds.me?.lid

		// Se não temos dados do grupo, não podemos verificar
		if (!groupData) {
			return { safe: true, reason: 'no_data' }
		}

		// Se o grupo NÃO é fechado (announce = false), é seguro enviar
		if (!groupData.announce) {
			return { safe: true, reason: 'group_open' }
		}

		// 🔐 GRUPO FECHADO DETECTADO - Verificações extras
		logger.debug({ jid, announce: groupData.announce }, '🛡️ Grupo fechado detectado - verificando permissões')

		// Verificar se o bot é admin
		const isAdmin = isBotAdminInGroup(groupData, meId, meLid)

		if (isAdmin) {
			// Verificar cooldown após promoção recente
			const promotionTime = ANNOUNCE_GROUP_PROTECTION.recentPromotions.get(jid)
			if (promotionTime) {
				const elapsed = Date.now() - promotionTime
				if (elapsed < ANNOUNCE_GROUP_PROTECTION.PROMOTION_COOLDOWN_MS) {
					const remaining = ANNOUNCE_GROUP_PROTECTION.PROMOTION_COOLDOWN_MS - elapsed
					logger.info({ 
						jid, 
						elapsed, 
						remaining 
					}, '🛡️ Promoção recente detectada - aguardando cooldown para segurança')
					
					// Aguardar o cooldown antes de enviar
					await delay(remaining + 500) // +500ms de margem
					
					// Limpar do cache de promoções
					ANNOUNCE_GROUP_PROTECTION.recentPromotions.delete(jid)
				}
			}
			
			return { safe: true, reason: 'is_admin' }
		}

		// Bot NÃO é admin no cache mas o grupo é fechado
		// Isso pode ser uma inconsistência de cache!
		logger.warn({ 
			jid, 
			announce: true, 
			isAdminInCache: false 
		}, '🛡️ ALERTA: Bot não é admin no cache de grupo fechado - forçando atualização de metadados')

		return { 
			safe: false, 
			reason: 'not_admin_in_announce_group',
			shouldRefresh: true 
		}
	}

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Verifica cooldown após bot ser adicionado ao grupo
	 * Retorna o tempo restante de cooldown em ms, ou 0 se já passou
	 * 
	 * IMPORTANTE: Cooldown é aplicado para TODOS os grupos, não apenas grandes
	 */
	const checkBotEntryCooldown = async (jid: string, groupSize?: number): Promise<number> => {
		const entryTime = BOT_ENTRY_PROTECTION.recentEntries.get(jid)
		if (!entryTime) return 0
		
		const now = Date.now()
		const elapsed = now - entryTime
		
		// Determinar cooldown baseado no tamanho do grupo
		// Se não souber o tamanho, usar cooldown mínimo de segurança
		const size = groupSize || BOT_ENTRY_PROTECTION.groupSizeCache.get(jid) || 0
		let cooldownMs: number
		
		if (size > 600) {
			// Grupo muito grande (> 600 membros)
			cooldownMs = BOT_ENTRY_PROTECTION.VERY_LARGE_GROUP_COOLDOWN_MS
		} else if (size > 300) {
			// Grupo grande (300-600 membros)
			cooldownMs = BOT_ENTRY_PROTECTION.LARGE_GROUP_COOLDOWN_MS
		} else if (size > 100) {
			// Grupo médio (100-300 membros)
			cooldownMs = BOT_ENTRY_PROTECTION.MEDIUM_GROUP_COOLDOWN_MS
		} else {
			// Grupo pequeno ou tamanho desconhecido - usar cooldown mínimo
			cooldownMs = BOT_ENTRY_PROTECTION.MIN_COOLDOWN_MS
		}
		
		if (elapsed < cooldownMs) {
			return cooldownMs - elapsed
		}
		
		// Cooldown passou, limpar cache
		BOT_ENTRY_PROTECTION.recentEntries.delete(jid)
		return 0
	}

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Registra quando o bot é adicionado a um grupo
	 * Deve ser chamado quando o bot detecta que foi adicionado
	 * 
	 * IMPORTANTE: Cooldown é aplicado para TODOS os grupos, independente do tamanho
	 */
	const registerBotEntry = (groupJid: string, groupSize?: number) => {
		BOT_ENTRY_PROTECTION.recentEntries.set(groupJid, Date.now())
		if (groupSize) {
			BOT_ENTRY_PROTECTION.groupSizeCache.set(groupJid, groupSize)
		}
		
		// Determinar cooldown baseado no tamanho do grupo
		let cooldownMs: number
		const size = groupSize || 0
		
		if (size > 600) {
			cooldownMs = BOT_ENTRY_PROTECTION.VERY_LARGE_GROUP_COOLDOWN_MS
		} else if (size > 300) {
			cooldownMs = BOT_ENTRY_PROTECTION.LARGE_GROUP_COOLDOWN_MS
		} else if (size > 100) {
			cooldownMs = BOT_ENTRY_PROTECTION.MEDIUM_GROUP_COOLDOWN_MS
		} else {
			// Grupo pequeno ou tamanho desconhecido - sempre aplicar cooldown mínimo
			cooldownMs = BOT_ENTRY_PROTECTION.MIN_COOLDOWN_MS
		}
		
		logger.info({ 
			groupJid, 
			groupSize: groupSize || 'unknown',
			cooldownSeconds: cooldownMs / 1000
		}, '🛡️ Bot adicionado ao grupo - cooldown de proteção ativado para QUALQUER grupo')
		
		// Auto-limpeza após o cooldown
		setTimeout(() => {
			BOT_ENTRY_PROTECTION.recentEntries.delete(groupJid)
			BOT_ENTRY_PROTECTION.groupSizeCache.delete(groupJid)
			logger.debug({ groupJid }, '🛡️ Cooldown de entrada expirou')
		}, cooldownMs + 1000)
	}

	const userDevicesCache =
		config.userDevicesCache ||
		new NodeCache<JidWithDevice[]>({
			stdTTL: DEFAULT_CACHE_TTLS.USER_DEVICES, // 5 minutes
			useClones: false
		})

	const peerSessionsCache = new NodeCache<boolean>({
		stdTTL: DEFAULT_CACHE_TTLS.USER_DEVICES,
		useClones: false
	})

	// Initialize message retry manager if enabled
	const messageRetryManager = enableRecentMessageCache ? new MessageRetryManager(logger, maxMsgRetryCount) : null

	/**
	 * 🔐 CONTROLE DE ENVIO DE SENDER KEYS E DISPOSITIVOS
	 * Limita para evitar congelamento em grupos grandes (900+ membros)
	 * e reduzir "mensagens invisíveis" para usuários
	 */
	const GROUP_LIMITS = {
		// Máximo de dispositivos para processar por mensagem
		MAX_DEVICES_PER_MESSAGE: 100,
		// Máximo de chaves para enviar por mensagem
		MAX_KEYS_PER_MESSAGE: 5,
		// Cooldown entre envios de chaves para o mesmo grupo (ms)
		COOLDOWN_MS: 3000,
		// Cache de último envio por grupo
		lastSendTime: new Map<string, number>()
	}

	// Prevent race conditions in Signal session encryption by user
	const encryptionMutex = makeKeyedMutex()

	let mediaConn: Promise<MediaConnInfo>
	const refreshMediaConn = async (forceGet = false) => {
		const media = await mediaConn
		if (!media || forceGet || new Date().getTime() - media.fetchDate.getTime() > media.ttl * 1000) {
			mediaConn = (async () => {
				const result = await query({
					tag: 'iq',
					attrs: {
						type: 'set',
						xmlns: 'w:m',
						to: S_WHATSAPP_NET
					},
					content: [{ tag: 'media_conn', attrs: {} }]
				})
				const mediaConnNode = getBinaryNodeChild(result, 'media_conn')!
				// TODO: explore full length of data that whatsapp provides
				const node: MediaConnInfo = {
					hosts: getBinaryNodeChildren(mediaConnNode, 'host').map(({ attrs }) => ({
						hostname: attrs.hostname!,
						maxContentLengthBytes: +attrs.maxContentLengthBytes!
					})),
					auth: mediaConnNode.attrs.auth!,
					ttl: +mediaConnNode.attrs.ttl!,
					fetchDate: new Date()
				}
				logger.debug('fetched media conn')
				return node
			})()
		}

		return mediaConn
	}

	/**
	 * generic send receipt function
	 * used for receipts of phone call, read, delivery etc.
	 * */
	const sendReceipt = async (
		jid: string,
		participant: string | undefined,
		messageIds: string[],
		type: MessageReceiptType
	) => {
		if (!messageIds || messageIds.length === 0) {
			throw new Boom('missing ids in receipt')
		}

		const node: BinaryNode = {
			tag: 'receipt',
			attrs: {
				id: messageIds[0]!
			}
		}
		const isReadReceipt = type === 'read' || type === 'read-self'
		if (isReadReceipt) {
			node.attrs.t = unixTimestampSeconds().toString()
		}

		if (type === 'sender' && (isPnUser(jid) || isLidUser(jid))) {
			node.attrs.recipient = jid
			node.attrs.to = participant!
		} else {
			node.attrs.to = jid
			if (participant) {
				node.attrs.participant = participant
			}
		}

		if (type) {
			node.attrs.type = type
		}

		const remainingMessageIds = messageIds.slice(1)
		if (remainingMessageIds.length) {
			node.content = [
				{
					tag: 'list',
					attrs: {},
					content: remainingMessageIds.map(id => ({
						tag: 'item',
						attrs: { id }
					}))
				}
			]
		}

		// Log reduzido para trace (operação frequente, não precisa aparecer por padrão)
		logger.trace({ attrs: node.attrs, messageIds }, 'sending receipt for messages')
		await sendNode(node)
	}

	/** Correctly bulk send receipts to multiple chats, participants */
	const sendReceipts = async (keys: WAMessageKey[], type: MessageReceiptType) => {
		const recps = aggregateMessageKeysNotFromMe(keys)
		for (const { jid, participant, messageIds } of recps) {
			await sendReceipt(jid, participant, messageIds, type)
		}
	}

	/** Bulk read messages. Keys can be from different chats & participants */
	const readMessages = async (keys: WAMessageKey[]) => {
		const privacySettings = await fetchPrivacySettings()
		// based on privacy settings, we have to change the read type
		const readType = privacySettings.readreceipts === 'all' ? 'read' : 'read-self'
		await sendReceipts(keys, readType)
	}

	/** Device info with wire JID */
	type DeviceWithJid = JidWithDevice & {
		jid: string
	}

	/** Fetch all the devices we've to send a message to */
	const getUSyncDevices = async (
		jids: string[],
		useCache: boolean,
		ignoreZeroDevices: boolean
	): Promise<DeviceWithJid[]> => {
		const deviceResults: DeviceWithJid[] = []

		if (!useCache) {
			logger.debug('not using cache for devices')
		}

		const toFetch: string[] = []

		const jidsWithUser = jids
			.map(jid => {
				const decoded = jidDecode(jid)
				const user = decoded?.user
				const device = decoded?.device
				const isExplicitDevice = typeof device === 'number' && device >= 0

				if (isExplicitDevice && user) {
					deviceResults.push({
						user,
						device,
						jid
					})
					return null
				}

				jid = jidNormalizedUser(jid)
				return { jid, user }
			})
			.filter(jid => jid !== null)

		let mgetDevices: undefined | Record<string, FullJid[] | undefined>

		if (useCache && userDevicesCache.mget) {
			const usersToFetch = jidsWithUser.map(j => j?.user).filter(Boolean) as string[]
			mgetDevices = await userDevicesCache.mget(usersToFetch)
		}

		for (const { jid, user } of jidsWithUser) {
			if (useCache) {
				const devices =
					mgetDevices?.[user!] ||
					(userDevicesCache.mget ? undefined : ((await userDevicesCache.get(user!)) as FullJid[]))
				if (devices) {
					const devicesWithJid = devices.map(d => ({
						...d,
						jid: jidEncode(d.user, d.server, d.device)
					}))
					deviceResults.push(...devicesWithJid)

					logger.trace({ user }, 'using cache for devices')
				} else {
					toFetch.push(jid)
				}
			} else {
				toFetch.push(jid)
			}
		}

		if (!toFetch.length) {
			return deviceResults
		}

		const requestedLidUsers = new Set<string>()
		for (const jid of toFetch) {
			if (isLidUser(jid) || isHostedLidUser(jid)) {
				const user = jidDecode(jid)?.user
				if (user) requestedLidUsers.add(user)
			}
		}

		const query = new USyncQuery().withContext('message').withDeviceProtocol().withLIDProtocol()

		for (const jid of toFetch) {
			query.withUser(new USyncUser().withId(jid)) // todo: investigate - the idea here is that <user> should have an inline lid field with the lid being the pn equivalent
		}

		const result = await sock.executeUSyncQuery(query)

		if (result) {
			// TODO: LID MAP this stuff (lid protocol will now return lid with devices)
			const lidResults = result.list.filter(a => !!a.lid)
			if (lidResults.length > 0) {
				logger.trace('Storing LID maps from device call')
				await signalRepository.lidMapping.storeLIDPNMappings(lidResults.map(a => ({ lid: a.lid as string, pn: a.id })))
			}

let extracted = extractDeviceJids(
				result?.list,
				authState.creds.me!.id,
				authState.creds.me!.lid!,
				ignoreZeroDevices
			)
			
			// 🔐 LIMITE DE DISPOSITIVOS: Evitar loop infinito em grupos grandes
			if (extracted.length > GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE) {
				logger.info({ 
					totalExtracted: extracted.length, 
					limiting: GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE 
				}, '🔐 Limitando dispositivos extraídos para evitar sobrecarga')
				extracted = extracted.slice(0, GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE)
			}
			
			const deviceMap: { [_: string]: FullJid[] } = {}

			for (const item of extracted) {
				deviceMap[item.user] = deviceMap[item.user] || []
				deviceMap[item.user]?.push(item)
			}

			// Process each user's devices as a group for bulk LID migration
			for (const [user, userDevices] of Object.entries(deviceMap)) {
				const isLidUser = requestedLidUsers.has(user)

				// Process all devices for this user
				for (const item of userDevices) {
					const finalJid = isLidUser
						? jidEncode(user, item.server, item.device)
						: jidEncode(item.user, item.server, item.device)

					deviceResults.push({
						...item,
						jid: finalJid
					})

					// Log removido para evitar spam - era a causa do loop infinito em grupos grandes
				}
			}

			if (userDevicesCache.mset) {
				// if the cache supports mset, we can set all devices in one go
				await userDevicesCache.mset(Object.entries(deviceMap).map(([key, value]) => ({ key, value })))
			} else {
				for (const key in deviceMap) {
					if (deviceMap[key]) await userDevicesCache.set(key, deviceMap[key])
				}
			}

			const userDeviceUpdates: { [userId: string]: string[] } = {}
			for (const [userId, devices] of Object.entries(deviceMap)) {
				if (devices && devices.length > 0) {
					userDeviceUpdates[userId] = devices.map(d => d.device?.toString() || '0')
				}
			}

			if (Object.keys(userDeviceUpdates).length > 0) {
				try {
					await authState.keys.set({ 'device-list': userDeviceUpdates })
					logger.debug(
						{ userCount: Object.keys(userDeviceUpdates).length },
						'stored user device lists for bulk migration'
					)
				} catch (error) {
					logger.warn({ error }, 'failed to store user device lists')
				}
			}
		}

		return deviceResults
	}

	const assertSessions = async (jids: string[]) => {
		let didFetchNewSession = false
		const uniqueJids = [...new Set(jids)] // Deduplicate JIDs
		const jidsRequiringFetch: string[] = []

		logger.debug({ jids }, 'assertSessions call with jids')

		// Check peerSessionsCache and validate sessions using libsignal loadSession
		for (const jid of uniqueJids) {
			const signalId = signalRepository.jidToSignalProtocolAddress(jid)
			const cachedSession = peerSessionsCache.get(signalId)
			if (cachedSession !== undefined) {
				if (cachedSession) {
					continue // Session exists in cache
				}
			} else {
				const sessionValidation = await signalRepository.validateSession(jid)
				const hasSession = sessionValidation.exists
				peerSessionsCache.set(signalId, hasSession)
				if (hasSession) {
					continue
				}
			}

			jidsRequiringFetch.push(jid)
		}

		if (jidsRequiringFetch.length) {
			// LID if mapped, otherwise original
			const wireJids = [
				...jidsRequiringFetch.filter(jid => !!isLidUser(jid) || !!isHostedLidUser(jid)),
				...(
					(await signalRepository.lidMapping.getLIDsForPNs(
						jidsRequiringFetch.filter(jid => !!isPnUser(jid) || !!isHostedPnUser(jid))
					)) || []
				).map(a => a.lid)
			]

			logger.debug({ jidsRequiringFetch, wireJids }, 'fetching sessions')
			const result = await query({
				tag: 'iq',
				attrs: {
					xmlns: 'encrypt',
					type: 'get',
					to: S_WHATSAPP_NET
				},
				content: [
					{
						tag: 'key',
						attrs: {},
						content: wireJids.map(jid => ({
							tag: 'user',
							attrs: { jid }
						}))
					}
				]
			})
			await parseAndInjectE2ESessions(result, signalRepository)
			didFetchNewSession = true

			// Cache fetched sessions using wire JIDs
			for (const wireJid of wireJids) {
				const signalId = signalRepository.jidToSignalProtocolAddress(wireJid)
				peerSessionsCache.set(signalId, true)
			}
		}

		return didFetchNewSession
	}

	const sendPeerDataOperationMessage = async (
		pdoMessage: proto.Message.IPeerDataOperationRequestMessage
	): Promise<string> => {
		//TODO: for later, abstract the logic to send a Peer Message instead of just PDO - useful for App State Key Resync with phone
		if (!authState.creds.me?.id) {
			throw new Boom('Not authenticated')
		}

		const protocolMessage: proto.IMessage = {
			protocolMessage: {
				peerDataOperationRequestMessage: pdoMessage,
				type: proto.Message.ProtocolMessage.Type.PEER_DATA_OPERATION_REQUEST_MESSAGE
			}
		}

		const meJid = jidNormalizedUser(authState.creds.me.id)

		const msgId = await relayMessage(meJid, protocolMessage, {
			additionalAttributes: {
				category: 'peer',

				push_priority: 'high_force'
			},
			additionalNodes: [
				{
					tag: 'meta',
					attrs: { appdata: 'default' }
				}
			]
		})

		return msgId
	}

	const createParticipantNodes = async (
		recipientJids: string[],
		message: proto.IMessage,
		extraAttrs?: BinaryNode['attrs'],
		dsmMessage?: proto.IMessage
	) => {
		if (!recipientJids.length) {
			return { nodes: [] as BinaryNode[], shouldIncludeDeviceIdentity: false }
		}

		const patched = await patchMessageBeforeSending(message, recipientJids)
		const patchedMessages = Array.isArray(patched)
			? patched
			: recipientJids.map(jid => ({ recipientJid: jid, message: patched }))

		let shouldIncludeDeviceIdentity = false
		const meId = authState.creds.me!.id
		const meLid = authState.creds.me?.lid
		const meLidUser = meLid ? jidDecode(meLid)?.user : null

		const encryptionPromises = (patchedMessages as any).map(
			async ({ recipientJid: jid, message: patchedMessage }: any) => {
				if (!jid) return null
				let msgToEncrypt = patchedMessage
				if (dsmMessage) {
					const { user: targetUser } = jidDecode(jid)!
					const { user: ownPnUser } = jidDecode(meId)!
					const ownLidUser = meLidUser
					const isOwnUser = targetUser === ownPnUser || (ownLidUser && targetUser === ownLidUser)
					const isExactSenderDevice = jid === meId || (meLid && jid === meLid)
					if (isOwnUser && !isExactSenderDevice) {
						msgToEncrypt = dsmMessage
						logger.debug({ jid, targetUser }, 'Using DSM for own device')
					}
				}

				const bytes = encodeWAMessage(msgToEncrypt)
				const mutexKey = jid
				const node = await encryptionMutex.mutex(mutexKey, async () => {
					const { type, ciphertext } = await signalRepository.encryptMessage({
						jid,
						data: bytes
					})
					if (type === 'pkmsg') {
						shouldIncludeDeviceIdentity = true
					}

					return {
						tag: 'to',
						attrs: { jid },
						content: [
							{
								tag: 'enc',
								attrs: {
									v: '2',
									type,
									...(extraAttrs || {})
								},
								content: ciphertext
							}
						]
					}
				})
				return node
			}
		)

		const nodes = (await Promise.all(encryptionPromises)).filter(node => node !== null) as BinaryNode[]
		return { nodes, shouldIncludeDeviceIdentity }
	}

	const relayMessage = async (
		jid: string,
		message: proto.IMessage,
		{
			messageId: msgId,
			participant,
			additionalAttributes,
			additionalNodes,
			useUserDevicesCache,
			useCachedGroupMetadata,
			statusJidList
		}: MessageRelayOptions
	) => {
		const meId = authState.creds.me!.id
		const meLid = authState.creds.me?.lid
		const isRetryResend = Boolean(participant?.jid)
		let shouldIncludeDeviceIdentity = isRetryResend
		const statusJid = 'status@broadcast'

		const { user, server } = jidDecode(jid)!
		const isGroup = server === 'g.us'
		const isStatus = jid === statusJid
		const isLid = server === 'lid'
		const isNewsletter = server === 'newsletter'
		const finalJid = jid

		// 🛡️ PROTEÇÃO ANTI-BAN: Verificar cooldown após bot ser adicionado ao grupo
		if (isGroup) {
			const remainingCooldown = await checkBotEntryCooldown(jid)
			if (remainingCooldown > 0) {
				logger.info({ 
					jid, 
					remainingMs: remainingCooldown,
					remainingSec: (remainingCooldown / 1000).toFixed(1)
				}, '🛡️ Cooldown de entrada ativo - aguardando antes de enviar mensagem')
				
				// Aguardar o cooldown restante
				await delay(remainingCooldown + 500)
				logger.debug({ jid }, '🛡️ Cooldown de entrada concluído - prosseguindo com envio')
			}
		}

		msgId = msgId || generateMessageIDV2(meId)
		useUserDevicesCache = useUserDevicesCache !== false
		useCachedGroupMetadata = useCachedGroupMetadata !== false && !isStatus

		const participants: BinaryNode[] = []
		const destinationJid = !isStatus ? finalJid : statusJid
		const binaryNodeContent: BinaryNode[] = []
		const devices: DeviceWithJid[] = []

		const meMsg: proto.IMessage = {
			deviceSentMessage: {
				destinationJid,
				message
			},
			messageContextInfo: message.messageContextInfo
		}

		const extraAttrs: BinaryNodeAttributes = {}

		if (participant) {
			if (!isGroup && !isStatus) {
				additionalAttributes = { ...additionalAttributes, device_fanout: 'false' }
			}

			const { user, device } = jidDecode(participant.jid)!
			devices.push({
				user,
				device,
				jid: participant.jid
			})
		}

		await authState.keys.transaction(async () => {
			const mediaType = getMediaType(message)
			if (mediaType) {
				extraAttrs['mediatype'] = mediaType
			}

			if (isNewsletter) {
				const patched = patchMessageBeforeSending ? await patchMessageBeforeSending(message, []) : message
				const bytes = encodeNewsletterMessage(patched as proto.IMessage)
				binaryNodeContent.push({
					tag: 'plaintext',
					attrs: {},
					content: bytes
				})
				const stanza: BinaryNode = {
					tag: 'message',
					attrs: {
						to: jid,
						id: msgId,
						type: getMessageType(message),
						...(additionalAttributes || {})
					},
					content: binaryNodeContent
				}
				logger.debug({ msgId }, `sending newsletter message to ${jid}`)
				await sendNode(stanza)
				return
			}

			if (normalizeMessageContent(message)?.pinInChatMessage) {
				extraAttrs['decrypt-fail'] = 'hide' // todo: expand for reactions and other types
			}

			if (isGroup || isStatus) {
				const [groupData, senderKeyMap] = await Promise.all([
					(async () => {
						// 🔐 SEMPRE buscar metadados frescos para garantir que novos participantes recebam chaves
						// O cache pode estar desatualizado e causar "Aguardando mensagem" para novos participantes
						if (!isStatus) {
							let fetchedData: any = undefined
							let shouldRefreshForSafety = false
							
							try {
								fetchedData = await groupMetadata(jid)
								logger.trace({ jid, participants: fetchedData?.participants?.length }, 'fetched fresh group metadata')
							} catch (err) {
								// Fallback para cache se a busca falhar
								if (useCachedGroupMetadata && cachedGroupMetadata) {
									fetchedData = await cachedGroupMetadata(jid)
									logger.trace({ jid, participants: fetchedData?.participants?.length }, 'using cached group metadata (fallback)')
								}
							}

							// 🛡️ PROTEÇÃO ANTI-BAN: Verificar segurança em grupos fechados
							if (fetchedData) {
								const safetyCheck = await checkAnnounceGroupSafety(jid, fetchedData)
								
								if (!safetyCheck.safe) {
									if (safetyCheck.shouldRefresh) {
										// Tentar buscar metadados frescos novamente para confirmar
										logger.info({ jid, reason: safetyCheck.reason }, 
											'🛡️ Forçando refresh de metadados por segurança...')
										
										try {
											const refreshedData = await groupMetadata(jid)
											
											// Verificar novamente com dados atualizados
											const secondCheck = await checkAnnounceGroupSafety(jid, refreshedData)
											
											if (secondCheck.safe) {
												logger.info({ jid, reason: secondCheck.reason }, 
													'🛡️ Verificação de segurança passou após refresh')
												fetchedData = refreshedData
											} else {
												// Ainda não é seguro - NÃO enviar para evitar ban
												logger.warn({ 
													jid, 
													announce: refreshedData?.announce,
													reason: secondCheck.reason 
												}, '🛡️ BLOQUEANDO envio: Bot não é admin em grupo fechado')
												
												// Marcar grupo como não-admin para evitar tentativas repetidas
												ANNOUNCE_GROUP_PROTECTION.notAdminGroups.add(jid)
												
												// Aguardar um tempo para dar chance de sincronização
												await delay(3000)
												
												// Buscar uma última vez
												const finalData = await groupMetadata(jid)
												const finalCheck = await checkAnnounceGroupSafety(jid, finalData)
												
												if (!finalCheck.safe) {
													throw new Error(`Cannot send message to announce group ${jid}: bot is not admin`)
												}
												
												fetchedData = finalData
												ANNOUNCE_GROUP_PROTECTION.notAdminGroups.delete(jid)
												logger.info({ jid }, '🛡️ Verificação final passou - enviando mensagem')
											}
										} catch (refreshErr: any) {
											if (refreshErr.message?.includes('Cannot send message to announce group')) {
												throw refreshErr
											}
											// Se não conseguiu fazer refresh, usar dados do cache e arriscar
											logger.warn({ jid, error: refreshErr }, 
												'🛡️ Não foi possível refresh - prosseguindo com dados do cache')
										}
									}
								}
							}
							
							return fetchedData
						}

						return undefined
					})(),
					(async () => {
						if (!participant && !isStatus) {
							// what if sender memory is less accurate than the cached metadata
							// on participant change in group, we should do sender memory manipulation
							const result = await authState.keys.get('sender-key-memory', [jid]) // TODO: check out what if the sender key memory doesn't include the LID stuff now?
							return result[jid] || {}
						}

						return {}
					})()
				])

				if (!participant) {
					const participantsList = []
					if (isStatus) {
						if (statusJidList?.length) participantsList.push(...statusJidList)
					} else {
						// default to LID based groups
						let groupAddressingMode = 'lid'
						if (groupData) {
							participantsList.push(...groupData.participants.map((p: { id: string }) => p.id))
							groupAddressingMode = groupData?.addressingMode || groupAddressingMode
						}

						// default to lid addressing mode in a group
						additionalAttributes = {
							...additionalAttributes,
							addressing_mode: groupAddressingMode
						}
					}

					const additionalDevices = await getUSyncDevices(participantsList, !!useUserDevicesCache, false)
					
					// 🔐 LIMITE DE DISPOSITIVOS: Evita congelamento em grupos grandes (900+)
					// Processa apenas um lote por mensagem, os demais receberão nas próximas
					if (additionalDevices.length > GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE) {
						logger.info({ 
							total: additionalDevices.length, 
							processing: GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE,
							group: jid 
						}, '🔐 Grupo grande detectado - limitando dispositivos para evitar congelamento')
						devices.push(...additionalDevices.slice(0, GROUP_LIMITS.MAX_DEVICES_PER_MESSAGE))
					} else {
						devices.push(...additionalDevices)
					}
				}

				if (groupData?.ephemeralDuration && groupData.ephemeralDuration > 0) {
					additionalAttributes = {
						...additionalAttributes,
						expiration: groupData.ephemeralDuration.toString()
					}
				}

				const patched = await patchMessageBeforeSending(message)
				if (Array.isArray(patched)) {
					throw new Boom('Per-jid patching is not supported in groups')
				}

				const bytes = encodeWAMessage(patched)
				const groupAddressingMode = additionalAttributes?.['addressing_mode'] || groupData?.addressingMode || 'lid'
				const groupSenderIdentity = groupAddressingMode === 'lid' && meLid ? meLid : meId

				const { ciphertext, senderKeyDistributionMessage } = await signalRepository.encryptGroupMessage({
					group: destinationJid,
					data: bytes,
					meId: groupSenderIdentity
				})

				const senderKeyRecipients: string[] = []
				const prioritySet = PRIORITY_PARTICIPANTS_CACHE.get(destinationJid)
				
				// 🔐 Primeiro, adiciona participantes PRIORITÁRIOS (que mandaram msg ou entraram no grupo)
				// Usamos cooldown de 10 minutos para evitar spam de chaves
				// Mas se passou o cooldown, forçamos reenvio (ignora senderKeyMap que pode estar desatualizado)
				if (prioritySet && prioritySet.size > 0) {
					for (const priorityJid of prioritySet) {
						// Verificar cooldown: só reenvia se passou 10 minutos desde último envio
						if (shouldSendKeyToParticipant(destinationJid, priorityJid)) {
							senderKeyRecipients.push(priorityJid)
							// Log apenas em trace para evitar spam
						}
					}
					// Limpar após processar
					PRIORITY_PARTICIPANTS_CACHE.delete(destinationJid)
				}
				
				// Depois, adiciona os demais dispositivos
				for (const device of devices) {
					const deviceJid = device.jid
					const hasKey = !!senderKeyMap[deviceJid]
					
					// Pular se já está na lista de prioritários
					if (senderKeyRecipients.includes(deviceJid)) {
						continue
					}
					
					if (
						(!hasKey || !!participant) &&
						!isHostedLidUser(deviceJid) &&
						!isHostedPnUser(deviceJid) &&
						device.device !== 99
					) {
						senderKeyRecipients.push(deviceJid)
					}
				}

				// 🔐 THROTTLE: Limitar envio de sender keys para evitar flood
				// Participantes prioritários SEMPRE são enviados primeiro
				let limitedRecipients = senderKeyRecipients
				if (senderKeyRecipients.length > GROUP_LIMITS.MAX_KEYS_PER_MESSAGE) {
					const now = Date.now()
					const lastSend = GROUP_LIMITS.lastSendTime.get(destinationJid) || 0
					
					// Se enviou recentemente, limitar para poucos destinatários
					if (now - lastSend < GROUP_LIMITS.COOLDOWN_MS) {
						limitedRecipients = senderKeyRecipients.slice(0, GROUP_LIMITS.MAX_KEYS_PER_MESSAGE)
						logger.debug({ 
							total: senderKeyRecipients.length, 
							sending: limitedRecipients.length,
							skipped: senderKeyRecipients.length - limitedRecipients.length
						}, '🔐 Throttling sender keys to prevent flood')
						
						// Marcar os não enviados como pendentes (serão enviados na próxima msg)
						for (let i = GROUP_LIMITS.MAX_KEYS_PER_MESSAGE; i < senderKeyRecipients.length; i++) {
							const jid = senderKeyRecipients[i]
							if (jid) senderKeyMap[jid] = false // Será enviado na próxima
						}
					}
					
					GROUP_LIMITS.lastSendTime.set(destinationJid, now)
				}

				// 🔐 ABORDAGEM DINÂMICA: Limite de chaves baseado em aquecimento
				// Durante aquecimento (após reconexão): 15 chaves/msg
				// Modo normal: 5 chaves/msg
				const dynamicKeysLimit = getKeysLimit(destinationJid)
				const keysToSend = limitedRecipients.slice(0, dynamicKeysLimit).filter((jid): jid is string => !!jid)
				
				if (keysToSend.length) {
					logger.debug({ 
						total: limitedRecipients.length,
						sending: keysToSend.length,
						limit: dynamicKeysLimit
					}, '🔐 Sending sender keys')

					const senderKeyMsg: proto.IMessage = {
						senderKeyDistributionMessage: {
							axolotlSenderKeyDistributionMessage: senderKeyDistributionMessage,
							groupId: destinationJid
						}
					}

					await assertSessions(keysToSend)
					const result = await createParticipantNodes(keysToSend, senderKeyMsg, extraAttrs)
					shouldIncludeDeviceIdentity = shouldIncludeDeviceIdentity || result.shouldIncludeDeviceIdentity
					participants.push(...result.nodes)
					
					// Marcar os enviados como tendo chave
					for (const jid of keysToSend) {
						senderKeyMap[jid] = true
						// 🔐 Registrar timestamp do envio para controle de cooldown
						markKeySentToParticipant(destinationJid, jid)
					}
					
					// Marcar os outros como pendentes para próxima mensagem
					for (let i = dynamicKeysLimit; i < limitedRecipients.length; i++) {
						const jid = limitedRecipients[i]
						if (jid) senderKeyMap[jid] = false
					}
				}

				if (isRetryResend) {
					const { type, ciphertext: encryptedContent } = await signalRepository.encryptMessage({
						data: bytes,
						jid: participant?.jid!
					})

					binaryNodeContent.push({
						tag: 'enc',
						attrs: {
							v: '2',
							type,
							count: participant!.count.toString()
						},
						content: encryptedContent
					})
				} else {
					binaryNodeContent.push({
						tag: 'enc',
						attrs: { v: '2', type: 'skmsg', ...extraAttrs },
						content: ciphertext
					})

					await authState.keys.set({ 'sender-key-memory': { [jid]: senderKeyMap } })
				}
			} else {
				// ADDRESSING CONSISTENCY: Match own identity to conversation context
				// TODO: investigate if this is true
				let ownId = meId
				if (isLid && meLid) {
					ownId = meLid
					logger.debug({ to: jid, ownId }, 'Using LID identity for @lid conversation')
				} else {
					logger.debug({ to: jid, ownId }, 'Using PN identity for @s.whatsapp.net conversation')
				}

				const { user: ownUser } = jidDecode(ownId)!

				if (!participant) {
					const targetUserServer = isLid ? 'lid' : 's.whatsapp.net'
					devices.push({
						user,
						device: 0,
						jid: jidEncode(user, targetUserServer, 0) // rajeh, todo: this entire logic is convoluted and weird.
					})

					if (user !== ownUser) {
						const ownUserServer = isLid ? 'lid' : 's.whatsapp.net'
						const ownUserForAddressing = isLid && meLid ? jidDecode(meLid)!.user : jidDecode(meId)!.user

						devices.push({
							user: ownUserForAddressing,
							device: 0,
							jid: jidEncode(ownUserForAddressing, ownUserServer, 0)
						})
					}

					if (additionalAttributes?.['category'] !== 'peer') {
						// Clear placeholders and enumerate actual devices
						devices.length = 0

						// Use conversation-appropriate sender identity
						const senderIdentity =
							isLid && meLid
								? jidEncode(jidDecode(meLid)?.user!, 'lid', undefined)
								: jidEncode(jidDecode(meId)?.user!, 's.whatsapp.net', undefined)

						// Enumerate devices for sender and target with consistent addressing
						const sessionDevices = await getUSyncDevices([senderIdentity, jid], true, false)
						devices.push(...sessionDevices)

						logger.debug(
							{
								deviceCount: devices.length,
								devices: devices.map(d => `${d.user}:${d.device}@${jidDecode(d.jid)?.server}`)
							},
							'Device enumeration complete with unified addressing'
						)
					}
				}

				const allRecipients: string[] = []
				const meRecipients: string[] = []
				const otherRecipients: string[] = []
				const { user: mePnUser } = jidDecode(meId)!
				const { user: meLidUser } = meLid ? jidDecode(meLid)! : { user: null }

				for (const { user, jid } of devices) {
					const isExactSenderDevice = jid === meId || (meLid && jid === meLid)
					if (isExactSenderDevice) {
						logger.debug({ jid, meId, meLid }, 'Skipping exact sender device (whatsmeow pattern)')
						continue
					}

					// Check if this is our device (could match either PN or LID user)
					const isMe = user === mePnUser || user === meLidUser

					if (isMe) {
						meRecipients.push(jid)
					} else {
						otherRecipients.push(jid)
					}

					allRecipients.push(jid)
				}

				await assertSessions(allRecipients)

				const [
					{ nodes: meNodes, shouldIncludeDeviceIdentity: s1 },
					{ nodes: otherNodes, shouldIncludeDeviceIdentity: s2 }
				] = await Promise.all([
					// For own devices: use DSM if available (1:1 chats only)
					createParticipantNodes(meRecipients, meMsg || message, extraAttrs),
					createParticipantNodes(otherRecipients, message, extraAttrs, meMsg)
				])
				participants.push(...meNodes)
				participants.push(...otherNodes)

				if (meRecipients.length > 0 || otherRecipients.length > 0) {
					extraAttrs['phash'] = generateParticipantHashV2([...meRecipients, ...otherRecipients])
				}

				shouldIncludeDeviceIdentity = shouldIncludeDeviceIdentity || s1 || s2
			}

			if (participants.length) {
				if (additionalAttributes?.['category'] === 'peer') {
					const peerNode = participants[0]?.content?.[0] as BinaryNode
					if (peerNode) {
						binaryNodeContent.push(peerNode) // push only enc
					}
				} else {
					binaryNodeContent.push({
						tag: 'participants',
						attrs: {},

						content: participants
					})
				}
			}

			const stanza: BinaryNode = {
				tag: 'message',
				attrs: {
					id: msgId,
					to: destinationJid,
					type: getMessageType(message),
					...(additionalAttributes || {})
				},
				content: binaryNodeContent
			}

			// if the participant to send to is explicitly specified (generally retry recp)
			// ensure the message is only sent to that person
			// if a retry receipt is sent to everyone -- it'll fail decryption for everyone else who received the msg
			if (participant) {
				if (isJidGroup(destinationJid)) {
					stanza.attrs.to = destinationJid
					stanza.attrs.participant = participant.jid
				} else if (areJidsSameUser(participant.jid, meId)) {
					stanza.attrs.to = participant.jid
					stanza.attrs.recipient = destinationJid
				} else {
					stanza.attrs.to = participant.jid
				}
			} else {
				stanza.attrs.to = destinationJid
			}

			if (shouldIncludeDeviceIdentity) {
				;(stanza.content as BinaryNode[]).push({
					tag: 'device-identity',
					attrs: {},
					content: encodeSignedDeviceIdentity(authState.creds.account!, true)
				})

				logger.debug({ jid }, 'adding device identity')
			}

			if (additionalNodes && additionalNodes.length > 0) {
				;(stanza.content as BinaryNode[]).push(...additionalNodes)
			}

			logger.debug({ msgId }, `sending message to ${participants.length} devices`)

			await sendNode(stanza)

			// Add message to retry cache if enabled
			if (messageRetryManager && !participant) {
				messageRetryManager.addRecentMessage(destinationJid, msgId, message)
			}
		}, meId)

		return msgId
	}

	const getMessageType = (message: proto.IMessage) => {
		if (message.pollCreationMessage || message.pollCreationMessageV2 || message.pollCreationMessageV3) {
			return 'poll'
		}

		if (message.eventMessage) {
			return 'event'
		}

		if (getMediaType(message) !== '') {
			return 'media'
		}

		return 'text'
	}

	const getMediaType = (message: proto.IMessage) => {
		if (message.imageMessage) {
			return 'image'
		} else if (message.videoMessage) {
			return message.videoMessage.gifPlayback ? 'gif' : 'video'
		} else if (message.audioMessage) {
			return message.audioMessage.ptt ? 'ptt' : 'audio'
		} else if (message.contactMessage) {
			return 'vcard'
		} else if (message.documentMessage) {
			return 'document'
		} else if (message.contactsArrayMessage) {
			return 'contact_array'
		} else if (message.liveLocationMessage) {
			return 'livelocation'
		} else if (message.stickerMessage) {
			return 'sticker'
		} else if (message.listMessage) {
			return 'list'
		} else if (message.listResponseMessage) {
			return 'list_response'
		} else if (message.buttonsResponseMessage) {
			return 'buttons_response'
		} else if (message.orderMessage) {
			return 'order'
		} else if (message.productMessage) {
			return 'product'
		} else if (message.interactiveResponseMessage) {
			return 'native_flow_response'
		} else if (message.groupInviteMessage) {
			return 'url'
		}

		return ''
	}

	const getPrivacyTokens = async (jids: string[]) => {
		const t = unixTimestampSeconds().toString()
		const result = await query({
			tag: 'iq',
			attrs: {
				to: S_WHATSAPP_NET,
				type: 'set',
				xmlns: 'privacy'
			},
			content: [
				{
					tag: 'tokens',
					attrs: {},
					content: jids.map(jid => ({
						tag: 'token',
						attrs: {
							jid: jidNormalizedUser(jid),
							t,
							type: 'trusted_contact'
						}
					}))
				}
			]
		})

		return result
	}

	const waUploadToServer = getWAUploadToServer(config, refreshMediaConn)

	const waitForMsgMediaUpdate = bindWaitForEvent(ev, 'messages.media-update')

	/**
	 * 🚀 SOLUÇÃO ZERO-DELAY: Envia SKDM proativamente para novo participante
	 * 
	 * Conforme Signal Protocol: quando um membro entra no grupo, membros existentes
	 * devem compartilhar suas sender keys via pairwise encryption para que o novo
	 * membro possa decriptar mensagens futuras sem delay.
	 * 
	 * @param groupJid - JID do grupo
	 * @param participantJid - JID do novo participante (LID ou PN)
	 */
	const sendProactiveSenderKey = async (groupJid: string, participantJid: string): Promise<void> => {
		try {
			const meId = authState.creds.me!.id
			
			// 1. Garantir que temos sessão com o participante
			await assertSessions([participantJid])
			
			// 2. Gerar SKDM do bot para este grupo
			// Usamos um buffer vazio pois só precisamos da SKDM, não de ciphertext
			const { senderKeyDistributionMessage } = await signalRepository.encryptGroupMessage({
				group: groupJid,
				meId: meId,
				data: Buffer.alloc(0)
			})
			
			// 3. Construir mensagem apenas com SKDM (sem conteúdo visível)
			const senderKeyMsg: proto.IMessage = {
				senderKeyDistributionMessage: {
					axolotlSenderKeyDistributionMessage: senderKeyDistributionMessage,
					groupId: groupJid
				}
			}
			
			// 4. Criar nó do participante para envio direto (pairwise)
			const { nodes, shouldIncludeDeviceIdentity } = await createParticipantNodes(
				[participantJid],
				senderKeyMsg,
				{}
			)
			
			if (nodes.length === 0) {
				logger.warn({ groupJid, participantJid }, 'No participant nodes created for proactive SKDM')
				return
			}
			
			// 5. Construir e enviar o nó da mensagem
			const msgId = generateMessageIDV2(meId)
			const stanza: BinaryNode = {
				tag: 'message',
				attrs: {
					id: msgId,
					to: groupJid,
					type: 'text',
					...(shouldIncludeDeviceIdentity ? { 'device_fanout': 'false' } : {})
				},
				content: [
					{
						tag: 'participants',
						attrs: {},
						content: nodes
					},
					{
						tag: 'enc',
						attrs: { v: '2', type: 'skmsg' },
						content: Buffer.alloc(0) // Mensagem vazia - só a SKDM importa
					}
				]
			}
			
			// 6. Enviar silenciosamente (não esperamos resposta)
			await sendNode(stanza)
			
			logger.info({ 
				groupJid, 
				participantJid, 
				msgId 
			}, '🚀 Proactive SKDM sent successfully - zero delay enabled!')
			
		} catch (error) {
			// Não falhar se não conseguir enviar SKDM proativo
			// O retry normal vai funcionar como fallback
			logger.warn({ 
				groupJid, 
				participantJid, 
				error 
			}, 'Failed to send proactive SKDM (fallback to normal retry)')
		}
	}

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Registra quando o bot é promovido a admin
	 * Isso permite que o sistema aplique cooldown antes de enviar mensagens
	 */
	const registerBotPromotion = (groupJid: string) => {
		ANNOUNCE_GROUP_PROTECTION.recentPromotions.set(groupJid, Date.now())
		// Limpar grupos marcados como não-admin
		ANNOUNCE_GROUP_PROTECTION.notAdminGroups.delete(groupJid)
		logger.info({ groupJid }, '🛡️ Promoção de bot registrada - cooldown ativo')
		
		// Auto-limpeza após o cooldown
		setTimeout(() => {
			ANNOUNCE_GROUP_PROTECTION.recentPromotions.delete(groupJid)
		}, ANNOUNCE_GROUP_PROTECTION.PROMOTION_COOLDOWN_MS + 1000)
	}

	/**
	 * 🛡️ PROTEÇÃO ANTI-BAN: Invalida cache de status admin para um grupo
	 * Usado quando há mudanças de configuração do grupo
	 */
	const invalidateAdminCache = (groupJid: string) => {
		ANNOUNCE_GROUP_PROTECTION.adminStatusCache.delete(groupJid)
		ANNOUNCE_GROUP_PROTECTION.notAdminGroups.delete(groupJid)
		logger.debug({ groupJid }, '🛡️ Cache de admin invalidado')
	}

	return {
		...sock,
		getPrivacyTokens,
		assertSessions,
		sendProactiveSenderKey,
		relayMessage,
		sendReceipt,
		sendReceipts,
		readMessages,
		refreshMediaConn,
		waUploadToServer,
		fetchPrivacySettings,
		sendPeerDataOperationMessage,
		createParticipantNodes,
		getUSyncDevices,
		messageRetryManager,
		// 🛡️ Funções de proteção anti-ban exportadas
		registerBotPromotion,
		invalidateAdminCache,
		registerBotEntry,
		updateMediaMessage: async (message: WAMessage) => {
			const content = assertMediaContent(message.message)
			const mediaKey = content.mediaKey!
			const meId = authState.creds.me!.id
			const node = await encryptMediaRetryRequest(message.key, mediaKey, meId)

			let error: Error | undefined = undefined
			await Promise.all([
				sendNode(node),
				waitForMsgMediaUpdate(async update => {
					const result = update.find(c => c.key.id === message.key.id)
					if (result) {
						if (result.error) {
							error = result.error
						} else {
							try {
								const media = await decryptMediaRetryData(result.media!, mediaKey, result.key.id!)
								if (media.result !== proto.MediaRetryNotification.ResultType.SUCCESS) {
									const resultStr = proto.MediaRetryNotification.ResultType[media.result!]
									throw new Boom(`Media re-upload failed by device (${resultStr})`, {
										data: media,
										statusCode: getStatusCodeForMediaRetry(media.result!) || 404
									})
								}

								content.directPath = media.directPath
								content.url = getUrlFromDirectPath(content.directPath!)

								logger.debug({ directPath: media.directPath, key: result.key }, 'media update successful')
							} catch (err: any) {
								error = err
							}
						}

						return true
					}
				})
			])

			if (error) {
				throw error
			}

			ev.emit('messages.update', [{ key: message.key, update: { message: message.message } }])

			return message
		},
		sendMessage: async (jid: string, content: AnyMessageContent, options: MiscMessageGenerationOptions = {}) => {
			const userJid = authState.creds.me!.id
			if (
				typeof content === 'object' &&
				'disappearingMessagesInChat' in content &&
				typeof content['disappearingMessagesInChat'] !== 'undefined' &&
				isJidGroup(jid)
			) {
				const { disappearingMessagesInChat } = content
				const value =
					typeof disappearingMessagesInChat === 'boolean'
						? disappearingMessagesInChat
							? WA_DEFAULT_EPHEMERAL
							: 0
						: disappearingMessagesInChat
				await groupToggleEphemeral(jid, value)
			} else {
				const fullMsg = await generateWAMessage(jid, content, {
					logger,
					userJid,
					getUrlInfo: text =>
						getUrlInfo(text, {
							thumbnailWidth: linkPreviewImageThumbnailWidth,
							fetchOpts: {
								timeout: 3_000,
								...(httpRequestOptions || {})
							},
							logger,
							uploadImage: generateHighQualityLinkPreview ? waUploadToServer : undefined
						}),
					//TODO: CACHE
					getProfilePicUrl: sock.profilePictureUrl,
					getCallLink: sock.createCallLink,
					upload: waUploadToServer,
					mediaCache: config.mediaCache,
					options: config.options,
					messageId: generateMessageIDV2(sock.user?.id),
					...options
				})
				const isEventMsg = 'event' in content && !!content.event
				const isDeleteMsg = 'delete' in content && !!content.delete
				const isEditMsg = 'edit' in content && !!content.edit
				const isPinMsg = 'pin' in content && !!content.pin
				const isPollMessage = 'poll' in content && !!content.poll
				const additionalAttributes: BinaryNodeAttributes = {}
				const additionalNodes: BinaryNode[] = []
				// required for delete
				if (isDeleteMsg) {
					// if the chat is a group, and I am not the author, then delete the message as an admin
					if (isJidGroup(content.delete?.remoteJid as string) && !content.delete?.fromMe) {
						additionalAttributes.edit = '8'
					} else {
						additionalAttributes.edit = '7'
					}
				} else if (isEditMsg) {
					additionalAttributes.edit = '1'
				} else if (isPinMsg) {
					additionalAttributes.edit = '2'
				} else if (isPollMessage) {
					additionalNodes.push({
						tag: 'meta',
						attrs: {
							polltype: 'creation'
						}
					} as BinaryNode)
				} else if (isEventMsg) {
					additionalNodes.push({
						tag: 'meta',
						attrs: {
							event_type: 'creation'
						}
					} as BinaryNode)
				}

				await relayMessage(jid, fullMsg.message!, {
					messageId: fullMsg.key.id!,
					useCachedGroupMetadata: options.useCachedGroupMetadata,
					additionalAttributes,
					statusJidList: options.statusJidList,
					additionalNodes
				})
				if (config.emitOwnEvents) {
					process.nextTick(() => {
						processingMutex.mutex(() => upsertMessage(fullMsg, 'append'))
					})
				}

				return fullMsg
			}
		}
	}
}
